def _target(value):
    value = " ".join((value or "").strip().casefold().replace("-", " ").split())
    return {"jee": "jee", "jee main": "jee_main", "jee mains": "jee_main",
            "jee advanced": "jee_advanced", "neet": "neet", "neet ug": "neet"}.get(value, "")


def classify_legacy_users(apps, schema_editor):
    User = apps.get_model("accounts", "User")
    users = User.objects.using(schema_editor.connection.alias).filter(role="STUDENT")
    for user in users.only("pk", "target_exam").iterator():
        value = _target(user.target_exam)
        track = "jee" if value in ("jee", "jee_main", "jee_advanced") else value
        if track:
            users.filter(pk=user.pk).update(exam_track=track)


